import { Router } from '../../../core/router/router';
import { Routes } from '../../../types';
import { WebSocketService } from '../../../api/Web-socket-service';
import { AuthState } from '../../../core/auth/Auth-state';
import { createElementWithClassId } from '../../../utils/helpers';
import { ButtonFactory } from '../Button';
import style from './chat.module.css';
import { ChatFooterFactory } from './Chat-footer';
import { ChatHeaderFactory } from './Chat-header';
import { ChatMain } from './Chat-main';
import { AboutLinkFactory } from '../about/about-link';
import { FLEX_CLASS } from '../../..';
export class Chat {
    constructor() {
        this._headerContainer = ChatHeaderFactory.createContainer();
        this._logoutErrorMessage = createElementWithClassId('div', [
            style['chat__logout-error'],
        ]);
        this._chatMain = new ChatMain();
        this._mainContainer = this._chatMain.createContainer();
        this._footerContainer = ChatFooterFactory.createContainer();
        Chat._updateErrorMessage(this._logoutErrorMessage, []);
        this._headerContainer.append(this._createLogoutButton());
    }
    get headerContainer() {
        return this._headerContainer;
    }
    get mainContainer() {
        return this._mainContainer;
    }
    get footerContainer() {
        return this._footerContainer;
    }
    get chatMain() {
        return this._chatMain;
    }
    static _updateErrorMessage(element, messages) {
        element.textContent = messages.join(', ');
    }
    _createLogoutButton() {
        const wrapper = createElementWithClassId('div', [
            style['chat__logout-wrapper'],
            FLEX_CLASS,
        ]);
        const button = ButtonFactory.create([style['chat__logout-button']], 'button', 'Logout');
        button.addEventListener('click', () => {
            Chat._updateErrorMessage(this._logoutErrorMessage, []);
            const user = AuthState.user;
            if (!user)
                return;
            const password = AuthState.password;
            if (!password)
                return;
            WebSocketService.logoutUser(user.login, password)
                .then(() => {
                Chat._updateErrorMessage(this._logoutErrorMessage, []);
                AuthState.clear();
                Router.navigateTo(Routes.Authentication);
            })
                .catch((errors) => {
                Chat._updateErrorMessage(this._logoutErrorMessage, [errors]);
            });
        });
        wrapper.append(this._logoutErrorMessage, button, AboutLinkFactory.createAboutLink());
        return wrapper;
    }
}
